@mcp_server.tool()
def set_device_parameter(
    track: Union[str, int],
    device: Union[str, int],
    parameter: str,
    value: float
) -> str:
    """
    Sets an exact parameter value on a Bitwig device or audio effect (e.g., EQ frequency, gain, Q, filter cutoff, reverb decay).

    Args:
        track: Track index or name.
        device: Device index or name.
        parameter: Exact parameter name (e.g. 'Frequency', 'Gain', 'Q', 'Cutoff', 'Resonance', 'Decay').
        value: Value to set. Hz for frequency/cutoff, dB for gain, float for Q.
    """
    payload = {"track": track, "device": device, "parameter": parameter, "value": value}
    res = executor.execute("set_device_parameter", payload)
    import json
    return json.dumps(res, indent=2)

